def is_plain_name(name: str) -> bool:
    """True when name is one ordinary path component: non-empty, not '.' or '..', no '/', '\\', ':' or NUL."""
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../secret") == False
    ex is_plain_name("/etc/passwd") == False
    ex is_plain_name("C:x") == False
    if name == "" or name == "." or name == "..":
        return False
    for c in name.chars():
        if c == "/" or c == "\\" or c == ":" or c == "\0":
            return False
    return True

def read_note(name: str) -> str uses fs:
    """Text of the file name inside fs, or "" when it is missing, unreadable or not a plain name. fs must already be confined to notes."""
    pre name.byte_len() < 4096
    pre is_plain_name(name)
    return fs.read_text(name) else ""

def count_readable(names: list[str]) -> int uses fs:
    """Count the names that are plain names and read as non-empty text from the notes directory. Names that are not plain, missing, unreadable or empty are not counted."""
    post out >= 0 and out <= names.len()
    count = 0
    with fs = fs.sub("notes"):
        for name in names:
            if name.byte_len() >= 4096:
                continue
            if not is_plain_name(name):
                continue
            text = read_note(name)
            if text != "":
                count += 1
    return count
